// Intended function: apply stack rules and emit periodic effect ticks without embedding damage/health ownership in the effect container.
#include "gameplay/EffectSystem.hpp"
#include <algorithm>
namespace elysium{void EffectSystem::registerDefinition(EffectDefinition d){defs_[d.effectId]=d;}bool EffectSystem::apply(ActiveEffect e){auto d=defs_.find(e.effectId);if(d==defs_.end()||!e.targetId)return false;std::vector<ActiveEffect*>same;for(auto&a:active_)if(a.targetId==e.targetId&&a.effectId==e.effectId)same.push_back(&a);if(!same.empty()&&d->second.stack!=EffectStackRule::Independent){auto*a=same.front();switch(d->second.stack){case EffectStackRule::Refresh:a->remaining=std::max(a->remaining,e.remaining);break;case EffectStackRule::AddDuration:a->remaining+=e.remaining;break;case EffectStackRule::AddMagnitude:a->magnitude=std::min(d->second.maxMagnitude,a->magnitude+e.magnitude);break;case EffectStackRule::ReplaceStronger:if(e.magnitude>a->magnitude)*a=e;break;default:break;}return true;}if(same.size()>=d->second.maxStacks)return false;active_.push_back(e);return true;}std::vector<EffectTick>EffectSystem::advance(float dt){std::vector<EffectTick>o;for(auto&a:active_){a.remaining-=dt;auto d=defs_.find(a.effectId);if(d==defs_.end())continue;auto&x=accum_[a.instanceId];x+=dt;while(x>=d->second.tickInterval){x-=d->second.tickInterval;o.push_back({a.sourceId,a.targetId,a.effectId,a.magnitude});}}active_.erase(std::remove_if(active_.begin(),active_.end(),[&](auto&a){if(a.remaining>0)return false;accum_.erase(a.instanceId);return true;}),active_.end());return o;}}
